import { Component, OnInit, inject, input, numberAttribute, signal } from '@angular/core';
import { Router } from '@angular/router';
import { Capacitor } from '@capacitor/core';
import { IonButton, IonContent, IonIcon } from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { checkmarkCircle, closeCircle } from 'ionicons/icons';

/**
 * Return page shown after Stripe checkout.
 * - Native (SFSafariViewController): Shows message + "close this tab" hint
 * - Web: Shows message + "Continue" button to navigate back into app
 */
@Component({
  selector: 'app-checkout-redirect',
  template: `
    <ion-content class="ion-padding">
      <div class="container">
        <ion-icon [name]="icon()" [color]="iconColor()" class="status-icon"></ion-icon>
        <h2>{{ title() }}</h2>
        <p>{{ message() }}</p>
        @if (isNative()) {
          <p class="hint">You can close this tab to return to Hey Bible.</p>
        } @else {
          <ion-button (click)="continue()" expand="block" class="continue-btn">
            Continue
          </ion-button>
        }
      </div>
    </ion-content>
  `,
  styles: [`
    .container {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100%;
      gap: 12px;
      max-width: 300px;
      margin: 0 auto;
      text-align: center;
    }
    .status-icon {
      font-size: 64px;
    }
    h2 {
      margin: 0;
      font-size: 22px;
      font-weight: 600;
    }
    p {
      margin: 0;
      color: var(--ion-color-medium);
      font-size: 16px;
    }
    .hint {
      margin-top: 8px;
      font-size: 14px;
      color: var(--ion-color-medium-shade);
    }
    .continue-btn {
      margin-top: 16px;
      width: 100%;
    }
  `],
  standalone: true,
  imports: [IonButton, IonContent, IonIcon],
})
export class CheckoutRedirectPage implements OnInit {
  private router = inject(Router);

  // Query params
  success = input<string>();
  credits = input(0, { transform: numberAttribute });
  cancelled = input<string>();

  // State
  title = signal('');
  message = signal('');
  icon = signal('checkmark-circle');
  iconColor = signal('success');
  isNative = signal(false);

  constructor() {
    addIcons({ checkmarkCircle, closeCircle });
  }

  ngOnInit() {
    this.isNative.set(Capacitor.isNativePlatform());

    if (this.success() === 'true') {
      const credits = this.credits();
      this.icon.set('checkmark-circle');
      this.iconColor.set('success');
      this.title.set('Purchase Complete!');
      this.message.set(credits > 0
        ? `${credits} credits have been added to your account.`
        : 'Credits have been added to your account.');
    } else {
      this.icon.set('close-circle');
      this.iconColor.set('medium');
      this.title.set('Purchase Cancelled');
      this.message.set('No charges were made.');
    }

    // Try to close the browser window (may work in some contexts on native)
    if (this.isNative()) {
      try {
        window.close();
      } catch {
        // Ignore - user will close manually
      }
    }
  }

  continue() {
    this.router.navigate(['/account']);
  }
}
